let today=null,game=null,phase='intro',busy=false,clockOffset=0,autoSent=false,correction=null,lastTick=-1,review=null,currentScore=0,paused=false,dialogPausePending=null,clockAtServer=0,visualScore=0,scoreAnimation=null,promptExitTimer=null;
const now=()=>Date.now()+clockOffset+clockAtServer;
const wait=ms=>new Promise(resolve=>setTimeout(resolve,testMode?Math.min(ms,40):ms));
