async function api(path,data){
  if(runtime.standalone)return localApi(path,data);
  const response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...(data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),signal:AbortSignal.timeout(15000)});
  const body=await response.json();if(!response.ok)throw new Error(body.error||'The signal is lost. Please retry.');return body;
}
let localRun=null;
function localState(){return {...localRun,serverNow:Date.now()};}
function localApi(path,data={}){
  const route=path.split('?')[0];
  if(route==='today')return Promise.resolve({date:'gift9',dayNumber:9,sample:false});
  if(route==='start'){
    localRun={runId:crypto.randomUUID(),date:'gift9',dayNumber:9,mode:'daily',prompts:DEMO.prompts,round:0,roundStart:Date.now()+3000,pausedAt:null,completed:false,results:[]};
    return Promise.resolve(localState());
  }
  if(route==='answer'){
    const prompt=localRun.prompts[localRun.round],raw=String(data.answer||'').trim();
    const match=raw?matchAnswer(raw,prompt.answers):null;
    if(match?.correction&&data.confirm!==true&&!data.timeout&&data.previewCorrection!==false)return Promise.resolve({correction:match.answer});
    if(raw&&!match&&!data.timeout)return Promise.resolve({rejected:true,message:`“${raw}”: no echo. try again`});
    const result={round:localRun.round,rawAnswer:raw||null,answer:match?.answer||null,tier:match?.tier||null,score:match?TIERS[match.tier].score:0,quip:match?.quip||null,promptText:prompt.text};
    localRun.results.push(result);localRun.round++;localRun.completed=localRun.round===7;localRun.roundStart=null;
    return Promise.resolve({result,state:localState()});
  }
  if(route==='next'){
    localRun.roundStart=Date.now()+3000;
    return Promise.resolve(localState());
  }
  if(route==='review')return Promise.resolve({prompts:DEMO.prompts.map(p=>({...p,answers:p.answers.map(a=>({...a,score:TIERS[a.tier].score}))}))});
  if(route==='pause')return Promise.resolve(localState());
  return Promise.reject(new Error('This action is unavailable in the staged game.'));
}
function setPhase(value){const card=$('prompt-card'),exiting=value==='plunge'&&!card.hidden;clearTimeout(promptExitTimer);card.classList.toggle('leaving',exiting);if(exiting)promptExitTimer=setTimeout(()=>{if(phase==='plunge')card.hidden=true;},testMode?40:650);phase=value;if(value!=='answering')document.body.classList.remove('timer-hot');document.body.dataset.phase=value;scene.setPhase(value);$('hero').hidden=false;$('intro').hidden=value!=='intro';card.hidden=!exiting&&!['preview','answering'].includes(value);$('answer-dock').hidden=value!=='answering';$('preview-label').hidden=value!=='preview';$('landing').hidden=value!=='landed';$('next-wrap').hidden=value!=='landed';$('results').hidden=value!=='done';$('falling-answer').hidden=value!=='plunge';$('tier-ladder').hidden=value!=='plunge';}
function applySettings(){scene.lowPower=settings.lowPower;document.body.classList.toggle('low-power',settings.lowPower);document.body.classList.toggle('colorblind',settings.colorblind);document.querySelectorAll('[data-setting]').forEach(input=>input.checked=!!settings[input.dataset.setting]);sound.mute(!!settings.muted);$('mute-btn').setAttribute('aria-pressed',String(!!settings.muted));$('mute-btn').setAttribute('aria-label',settings.muted?'Turn sound on':'Turn sound off');$('mute-btn').innerHTML=`<svg viewBox="0 0 20 16" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true"><path d="M2 6h3l4-4v12l-4-4H2z"/>${settings.muted?'<path d="m12 5 5 6m0-6-5 6" stroke="currentColor" stroke-width="2"/>':'<path d="M11 6h2v4h-2zm4-3h2v10h-2z"/>'}</svg>`;$('mascot').dataset.buddy=settings.buddy;const buddy=buddyOptions.find(b=>b.id===settings.buddy)||buddyOptions[0];$('mascot').querySelector('img').src=buddy.src;$('mascot').querySelector('img').alt=buddy.name;syncBuddyGold();}
const buddyOptions=[{id:'krill',name:'The Krill',streak:0,src:'./assets/krill.svg'},{id:'schooler',name:'Schooler',streak:5,src:'./assets/schooler.svg'},{id:'rare',name:'Rare Squid',streak:14,src:'./assets/rare.svg'},{id:'deepcut',name:'Deep Cut Angler',streak:30,src:'./assets/deepcut.svg'},{id:'evil',name:'Evil Krill',streak:45,src:'./assets/evil.svg'}];
applySettings();
function updateHud(){const results=game?.results||[];currentScore=results.reduce((s,r)=>s+r.score,0);$('score').textContent=Math.round(visualScore);$('depth').textContent=Math.round(scene.depth).toLocaleString('en-US')+'m';$('round-label').textContent=game?(game.completed?'DIVE COMPLETE':`PROMPT ${Math.min(7,game.round+1)} OF 7`):'SURFACE';document.querySelectorAll('#round-dots i').forEach((dot,i)=>{const r=results.find(r=>r.round===i);dot.className=r?'done':i===(game?.round??-1)?'active':'';dot.style.setProperty('--dot-color',r?'#ffd166':'#26364b')});}
function saveRun(){if(!game)return;write('ok:run',{runId:game.runId,date:game.date,mode:game.mode});}
function setGame(value){game=value;clockOffset=0;clockAtServer=typeof game.serverNow==='number'?game.serverNow-Date.now():0;visualScore=game.results.reduce((sum,r)=>sum+r.score,0);saveRun();updateHud();}
async function begin(practice=false){if(busy)return;busy=true;$('start-btn').disabled=true;$('boot-error').hidden=true;await sound.init();try{const response=await api('start',{practice});setGame(response);sound.event('begin');scene.targetActive=1;review=null;if(game.completed){await showResults();return;}if(game.roundStart===null&&game.results.length){const last=game.results.at(-1);showLanding({...last,promptText:game.prompts[last.round]?.text});}else showRound();track('Dive Started',{mode:game.mode,day:game.dayNumber});}catch(e){setPhase('intro');$('boot-error').textContent=e.message;$('boot-error').hidden=false;}finally{busy=false;$('start-btn').disabled=false;}}
function showRound(){setPhase('preview');syncBuddyGold();correction=null;autoSent=false;lastTick=-1;$('answer-status').textContent='';$('answer-status').className='answer-status';const p=game.prompts[game.round];$('prompt-number').textContent=`PROMPT ${game.round+1} OF 7`;$('prompt-text').textContent=p.text;$('answer').value=read('ok:draft:'+game.runId+':'+game.round,'');$('answer').disabled=true;$('submit-btn').disabled=true;scene.setDepth(currentScore*10);scene.roundBase=currentScore*10;scene.roundIndex=game.round;scene.round(currentScore*10);tick();}
async function submit(timeout=false){if(!game||busy||!['preview','answering'].includes(phase)||paused)return;const raw=$('answer').value.trim();if(!raw&&!timeout)return;busy=true;$('submit-btn').disabled=true;try{const response=await api('answer',{runId:game.runId,round:game.round,answer:raw,timeout,confirm:correction===raw,previewCorrection:settings.corrections});if(response.rejected){$('answer-status').className='answer-status';$('answer-status').textContent=response.message;sound.event('reject');$('answer').classList.remove('shake');void $('answer').offsetWidth;$('answer').classList.add('shake');if(settings.clearRejected)$('answer').value='';correction=null;}else if(response.correction){correction=response.correction;$('answer-status').className='answer-status correction';$('answer-status').innerHTML=`“${escape(raw)}” → “${escape(correction)}”`;$('answer').value=correction;write('ok:draft:'+game.runId+':'+game.round,correction);}else if(response.alreadyScored){setGame(response.state);if(game.completed)await showResults();else if(game.roundStart===null)showLanding(game.results.at(-1));else showRound();}else{const oldScore=currentScore;setGame(response.state);sound.event('submit');{const rect=$('answer').getBoundingClientRect();for(let i=0;i<12;i++)scene.typeAt(rect.left+Math.random()*rect.width,rect.top+Math.random()*rect.height,1);}track('Answer Scored',{mode:game.mode,round:response.result.round+1,tier:response.result.tier||'miss'});await plunge(response.result,oldScore);}}catch(e){$('answer-status').textContent=e.message;$('answer-status').className='answer-status';}finally{busy=false;if(phase==='answering'){$('submit-btn').disabled=!$('answer').value.trim();$('answer').focus({preventScroll:true});}}}
function animateScore(from,to,gold=false){
  if(scoreAnimation)cancelAnimationFrame(scoreAnimation);
  const started=performance.now(),duration=testMode?60:gold?1100:700;
  const frame=t=>{const p=Math.min(1,(t-started)/duration),e=1-(1-p)**4;visualScore=from+(to-from)*e;scene.depth=visualScore*10;$('score').textContent=Math.round(visualScore);if(p<1)scoreAnimation=requestAnimationFrame(frame);else{visualScore=to;if(gold){$('score').classList.add('slam');setTimeout(()=>$('score').classList.remove('slam'),520);}}};
  scoreAnimation=requestAnimationFrame(frame);
}
async function plunge(result,oldScore){
  setPhase('plunge');document.body.dataset.tier=result.tier||'miss';visualScore=oldScore;updateHud();scene.roundIndex=game.round;
  const fall=$('falling-answer'),ladder=$('tier-ladder');fall.textContent=result.answer?`“${result.answer.toUpperCase()}”`:'';fall.style.color=TIERS[result.tier]?.color||'#7d93b8';fall.style.setProperty('--chip-color',TIERS[result.tier]?.color||'#7d93b8');
  ladder.innerHTML=result.tier?Object.entries(TIERS).map(([id,t])=>`<div class="tier-line" data-tier="${id}" data-score="${t.score}" style="--line-color:${t.color}"><span>${tierImage(id)}${t.name.toUpperCase()} · ${t.score}</span></div>`).join(''):'';
  const duration=testMode?80:DROP_MS[result.tier||'miss'],began=performance.now();let lastPassed=-1;
  if(result.tier)sound.event('sink');else{sound.event('miss');$('game').classList.add('shake');setTimeout(()=>$('game').classList.remove('shake'),500);}
  await new Promise(resolve=>{const frame=t=>{const p=Math.min(1,(t-began)/duration),e=easeInOut(p);scene.drop(oldScore*10,result,p);const sway=result.tier==='plankton'?36*Math.sin(p*7)*(1-.25*p):result.tier==='tooclever'?7*Math.sin(p*42):Math.sin(p*(result.tier==='krillion'?24:16))*(1-p)*(result.tier==='krillion'?26:14);fall.style.left=`calc(50% - 24px + ${sway}px)`;fall.style.rotate=(sway*(result.tier==='plankton'?.55:.4))+'deg';fall.style.top=(scene.layout().height/2-60)+'px';
    const travelled=90+(result.score*10-90)*e;Array.from(ladder.children).forEach((line,i)=>{if(travelled>=Number(line.dataset.score)*10-4&&!line.classList.contains('active')){line.classList.add('active');if(i>lastPassed){sound.event('tier');lastPassed=i;}}});
    if(p<1)requestAnimationFrame(frame);else{scene.cameraDepth=scene.cameraTarget;resolve();}};requestAnimationFrame(frame);});
  showLanding(result,oldScore);
}
function showLanding(result,oldScore=currentScore-result.score){
  setPhase('landed');const tier=TIERS[result.tier];document.body.dataset.tier=result.tier||'miss';document.documentElement.style.setProperty('--tier',tier?.color||'#7d93b8');
  const icon=$('land-icon');icon.hidden=!tier;icon.src='./assets/'+(iconFor(result.tier)||'plankton')+'.svg';icon.style.visibility=result.tier==='krillion'?'hidden':'visible';
  $('land-tier').textContent=tier?.name.toUpperCase()||'NOTHING LANDED';$('land-answer').textContent=result.answer?`“${result.answer}”`:'—';$('land-points').innerHTML=`<b>+${result.score} PTS</b>${result.score?' · sink '+(result.score*10).toLocaleString('en-US')+'m':''}`;
  $('land-quip').textContent=result.quip||tier?.blurb||(result.rawAnswer?'never made it onto the reef.':'the clock beat you to it.');$('next-btn').textContent=game.completed?'SURFACE ▲':'DESCEND ▼';
  if(tier)sound.event(result.tier);scene.target=currentScore*10;scene.roundIndex=game.round;
  if(!scene.fx)scene.fx={tier:result.tier,progress:1};
  scene.moveCamera(currentScore*10+30,testMode?1:500);
  const gold=result.tier==='krillion';visualScore=oldScore;
  if(gold){$('mascot').classList.remove('celebrate');void $('mascot').offsetWidth;$('mascot').classList.add('celebrate');setTimeout(()=>$('mascot').classList.remove('celebrate'),testMode?30:1250);scene.goldLandAt=performance.now();setTimeout(()=>{if(phase!=='landed'||game.results.at(-1)?.round!==result.round)return;syncBuddyGold();scene.burst('#ffd166',42);animateScore(oldScore,currentScore,true);},testMode?20:1000);}else animateScore(oldScore,currentScore);
  if(['rare','tooclever'].includes(result.tier)){$('game').classList.add('shake');setTimeout(()=>$('game').classList.remove('shake'),500);}
  if(result.score>=60){scene.burst(tier.color,result.score===100?36:22);document.querySelector('.flash').style.background=tier.color;document.querySelector('.flash').classList.remove('on');void document.querySelector('.flash').offsetWidth;document.querySelector('.flash').classList.add('on');}
  if(!gold)syncBuddyGold();updateHud();
}
async function next(){if(busy)return;busy=true;try{if(game.completed){sound.event('surface');const duration=Math.min(9000,Math.max(2500,(currentScore*10+30)*3));scene.moveCamera(-45,testMode?1:duration,easeOut);await showResults();return;}sound.event('begin');const data=await api('next',{runId:game.runId});setGame(data);showRound();}catch(e){$('land-quip').textContent=e.message;}finally{busy=false;}}
function syncBuddyGold(){const gold=game?.results.some(r=>r.tier==='krillion');$('mascot').classList.toggle('gold',!!gold);if(settings.buddy==='krill')$('mascot').querySelector('img').src=gold?'./assets/krill-gold.svg':'./assets/krill.svg';}
function historyStats(){const history=read('ok:history',{}),daily=Object.values(history).filter(r=>r.mode==='daily').sort((a,b)=>a.date.localeCompare(b.date));let bestStreak=0,streak=0,last=null;for(const r of daily){streak=last&&Date.parse(r.date)-Date.parse(last)===86400000?streak+1:1;bestStreak=Math.max(bestStreak,streak);last=r.date;}const diff=last?(Date.parse(etDate())-Date.parse(last))/86400000:Infinity;const current=diff<=1?streak:0;return{history,daily,played:daily.length,current,bestStreak,best:Math.max(0,...daily.map(r=>r.score)),average:daily.length?Math.round(daily.reduce((s,r)=>s+r.score,0)/daily.length):0};}
function storeHistory(){const history=read('ok:history',{}),key=game.mode==='daily'?game.date:game.runId;history[key]={date:game.date,dayNumber:game.dayNumber,mode:game.mode,score:currentScore,results:game.results};write('ok:history',history);}
function chart(results){return diveChart(results,escape);}
async function showResults(){setPhase('done');visualScore=currentScore;syncBuddyGold();scene.setDepth(0);review=null;storeHistory();$('results').innerHTML=`<section class="golden-finish"><h2>YOU'RE ONE IN A KRILLION</h2></section><div class="answer-review" id="answer-review"><p class="muted">Loading answers…</p></div><div class="results-actions"><button class="results-play-again" data-play-again>Play Again</button><button class="results-close" data-close-results>Close</button></div>`;$('results').scrollTop=0;updateHud();try{review=await api('review?run='+encodeURIComponent(game.runId));if(phase!=='done')return;$('answer-review').innerHTML=review.prompts.map((prompt,i)=>{const result=game.results[i];return `<section class="answer-question"><button class="answer-question-toggle" data-review="${i}" aria-expanded="false"><span class="review-index">${i+1}</span><span class="review-icon">${result.tier?`<img src="./assets/${iconFor(result.tier)||'plankton'}.svg" alt="">`:''}</span><span class="review-copy"><small>${escape(prompt.text)}</small><strong>${result.answer?`“${escape(result.answer)}”`:'No answer'}</strong></span><span class="review-points" style="--tier:${TIERS[result.tier]?.color||'#7d93b8'}">${result.score?`+${result.score}`:'—'}</span><span class="review-sign">+</span></button><div class="answer-question-detail" hidden></div></section>`}).join('');}catch{$('answer-review').innerHTML='<p class="muted">Accepted answers could not be loaded.</p>';}}
function resultText(){let text=shareText(game.dayNumber,game.results);if(!settings.shareLink)text=text.replace('\n','');if(game.mode==='practice')text=text.replace('Christmillion #','Christmillion practice #');return text;}
async function copyResult(button){try{await navigator.clipboard.writeText(resultText());button.textContent='Copied ✓';track('Result Copied',{score:currentScore});setTimeout(()=>button.textContent='Copy result',2200);}catch{button.textContent='Select and copy below';const box=document.createElement('textarea');box.value=resultText();box.readOnly=true;box.style.width='100%';button.parentElement.after(box);box.select();}}
async function expandReview(button){const i=Number(button.dataset.review),box=button.nextElementSibling,open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.querySelector('.review-sign').textContent=open?'+':'−';box.hidden=open;if(open)return;if(!review){box.innerHTML='<p class="muted">Loading accepted answers…</p>';try{review=await api('review?run='+encodeURIComponent(game.runId));}catch{box.innerHTML='<p class="muted">Could not load answers. Close and try again.</p>';return;}}const answers=review.prompts[i].answers,own=game.results[i].answer,tiers=Object.entries(TIERS).filter(([tier])=>answers.some(a=>a.tier===tier));box.innerHTML=`<nav class="review-filters" aria-label="Filter answers"><button class="active" data-tier-filter="all">All ${answers.length}</button>${tiers.map(([tier,info])=>`<button data-tier-filter="${tier}" style="--tier:${info.color}">${info.name}</button>`).join('')}</nav><input class="search-answers" aria-label="Search accepted answers" placeholder="Search ${answers.length} answers…"><ul class="review-list">${answers.map(a=>`<li data-tier="${a.tier}" data-answer="${escape(a.answer.toLowerCase())}" style="--tier:${TIERS[a.tier].color}"><span>${escape(a.answer)}${a.answer===own?'<b class="you">YOU</b>':''}</span><span>+${a.score}</span></li>`).join('')}</ul>`;}
function openWardrobe(){const best=historyStats().bestStreak;$('buddy-list').innerHTML=buddyOptions.map(b=>`<button data-buddy="${b.id}" aria-pressed="${settings.buddy===b.id}" ${best<b.streak?'disabled':''}><img src="${b.src}" alt=""><span>${b.name}</span><small>${best>=b.streak?'Earned':b.streak+'-day streak'}</small></button>`).join('');openDialog('wardrobe-dialog');}
async function pauseGame(){if(!game||!['preview','answering'].includes(phase)||paused)return;paused=true;try{dialogPausePending=api('pause',{runId:game.runId,paused:true});setGame(await dialogPausePending);}catch{paused=false;}finally{dialogPausePending=null;}}
async function resumeGame(){if(document.querySelector('dialog[open]')||!paused)return;const rid=game.runId;try{if(dialogPausePending)await dialogPausePending;const resumed=await api('pause',{runId:rid,paused:false});if(game.runId===rid)setGame(resumed);paused=false;tick();}catch{$('answer-status').textContent='Could not resume. Reopen the menu and try again.';}}
function openDialog(id){document.querySelectorAll('dialog[open]').forEach(d=>d.close());$(id).showModal();void pauseGame();}
function doAction(action){document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(action==='daily'){if(game?.mode==='daily'){if(game.completed)void showResults();else if(game.roundStart===null)showLanding(game.results.at(-1));else showRound();}else void begin(false);}if(action==='settings')openDialog('settings-dialog');}
function tick(){if(game&&['preview','answering'].includes(phase)&&!paused){const remaining=game.roundStart+ROUND_MS-now();if(now()<game.roundStart){const count=Math.max(1,Math.ceil((game.roundStart-now())/1000));$('preview-label').textContent=`descending · the clock starts in ${count}`;$('timer-number').textContent=count;document.documentElement.style.setProperty('--time',1);}else{if(phase==='preview'){setPhase('answering');$('answer').disabled=false;$('preview-label').textContent='';$('answer').focus({preventScroll:true});}$('submit-btn').disabled=busy||!$('answer').value.trim();const seconds=Math.max(0,Math.ceil(remaining/1000));document.body.classList.toggle('timer-hot',remaining<=3050);$('timer-number').textContent=seconds;document.documentElement.style.setProperty('--time',Math.max(0,remaining/ROUND_MS));document.documentElement.style.setProperty('--urgency',seconds<=3&&!scene.reduced?(1-seconds/4)*(.35+Math.sin(Date.now()*.012)*.2):0);if(seconds>0&&seconds<=3&&seconds!==lastTick){sound.event('tick');lastTick=seconds;}if(remaining<=0&&!autoSent&&!busy){autoSent=true;void submit(true);}}}else document.documentElement.style.setProperty('--urgency',0);if($('reset-countdown')&&game){const d=Math.max(0,(game.resetsAt-Date.now())/1000),h=Math.floor(d/3600),m=Math.floor(d%3600/60),s=Math.floor(d%60);$('reset-countdown').textContent=`next dive in ${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}if(game)$('depth').textContent=Math.round(scene.depth).toLocaleString('en-US')+'m';}
$('start-btn').addEventListener('click',()=>begin(false));$('menu-btn').addEventListener('click',()=>openDialog('menu-dialog'));$('settings-btn').addEventListener('click',()=>openDialog('settings-dialog'));$('wardrobe-btn').addEventListener('click',openWardrobe);$('next-btn').addEventListener('click',next);
$('mute-btn').addEventListener('click',async()=>{await sound.init();settings.muted=!settings.muted;write('ok:settings',settings);applySettings();});$('mascot').addEventListener('click',async()=>{await sound.init();sound.event('blub');$('mascot').classList.remove('poked');void $('mascot').offsetWidth;$('mascot').classList.add('poked');setTimeout(()=>$('mascot').classList.remove('poked'),1000)});
$('answer-form').addEventListener('submit',e=>{e.preventDefault();void submit(false)});$('answer').addEventListener('input',()=>{const r=$('answer').getBoundingClientRect();scene.typeAt(r.left+14+Math.min(11*$('answer').value.length,r.width-28),r.top+5);write('ok:draft:'+game.runId+':'+game.round,$('answer').value);if(correction!==$('answer').value){correction=null;$('answer-status').textContent=''}tick()});
document.addEventListener('click',e=>{if(e.target.closest('[data-play-again]')){void begin(false);return;}if(e.target.closest('[data-close-results]')){parent.postMessage({type:'christmillion-close'},'*');return;}const close=e.target.closest('[data-close]');if(close)close.closest('dialog').close();const action=e.target.closest('[data-action]');if(action)doAction(action.dataset.action);const f=e.target.closest('[data-tier-filter]');if(f){f.parentElement.querySelectorAll('[data-tier-filter]').forEach(b=>b.classList.toggle('active',b===f));filterReview(f.closest('.answer-question-detail'));}const r=e.target.closest('[data-review]');if(r)void expandReview(r);const copy=e.target.closest('#copy-result');if(copy)void copyResult(copy);if(e.target.closest('#native-share'))navigator.share?.({text:resultText()}).catch(()=>{});const buddy=e.target.closest('[data-buddy]');if(buddy){settings.buddy=buddy.dataset.buddy;write('ok:settings',settings);applySettings();openWardrobe()}const rating=e.target.closest('[data-rating]');if(rating){api('feedback',{kind:'rating',text:rating.dataset.rating}).then(()=>{document.querySelectorAll('[data-rating]').forEach(b=>b.setAttribute('aria-pressed',String(b===rating)));$('rating-status').textContent='Thanks for the feedback.'}).catch(err=>$('rating-status').textContent=err.message)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-setting]')){settings[e.target.dataset.setting]=e.target.checked;write('ok:settings',settings);applySettings()}});
function filterReview(box){if(!box)return;const text=box.querySelector('.search-answers')?.value.toLowerCase()||'',tier=box.querySelector('[data-tier-filter].active')?.dataset.tierFilter||'all';box.querySelectorAll('.review-list li').forEach(li=>li.hidden=(!li.dataset.answer.includes(text))||(tier!=='all'&&li.dataset.tier!==tier));}
document.addEventListener('input',e=>{if(e.target.matches('.search-answers'))filterReview(e.target.closest('.answer-question-detail'));});
document.addEventListener('submit',e=>{if(e.target.id==='suggestion-form'){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;api('feedback',{kind:'suggestion',text:$('suggestion').value}).then(()=>{$('suggestion-status').textContent='Thanks — noted.';$('suggestion').value=''}).catch(err=>$('suggestion-status').textContent=err.message).finally(()=>button.disabled=false)}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>void resumeGame());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});

document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)&&!e.ctrlKey&&!e.metaKey){if(document.fullscreenElement)document.exitFullscreen?.();else $('game').requestFullscreen?.().catch(()=>{})}});
function viewport(){const height=window.visualViewport?.height||innerHeight;document.documentElement.style.setProperty('--vh',height+'px')}viewport();window.visualViewport?.addEventListener('resize',viewport);window.addEventListener('resize',viewport);
window.render_game_to_text=()=>JSON.stringify({phase,prompt:game?.prompts[game.round]?.text||null,round:game?.round??0,totalRounds:7,score:Math.round(visualScore),targetScore:currentScore,depth:Math.round(scene.depth),targetDepth:scene.target,cameraDepth:Math.round(scene.cameraDepth),effect:scene.fx?.tier||null,seconds:game?Math.max(0,Math.ceil((game.roundStart+ROUND_MS-now())/1000)):null,results:game?.results.map(r=>({answer:r.answer,tier:r.tier,score:r.score}))||[],draft:$('answer').value,correction,mode:game?.mode||'daily',paused,sound:{supported:!!(window.AudioContext||window.webkitAudioContext),state:sound.ac?.state||'not-started',muted:sound.muted},coordinates:'origin at top-left, x rightward, y downward; depth in metres',lowPower:settings.lowPower});
window.advanceTime=async ms=>{if(!runtime.local)return;clockOffset+=Math.max(0,ms);scene.time+=ms/1000;scene.depth=scene.target;scene.active=scene.targetActive;scene.cameraDepth=scene.cameraTarget;scene.cameraJob=null;scene.draw();tick();await new Promise(r=>setTimeout(r,0));};
setInterval(tick,80);
(async()=>{try{today=await api('today');$('day-number').textContent=runtime.standalone?'GIFT #9':'DIVE #'+today.dayNumber;if($('sample-note'))$('sample-note').hidden=!today.sample;}catch(e){$('boot-error').textContent=e.message;$('boot-error').hidden=false;}})();
